// This file is not generated by Stainless and is preserved across codegen runs.
// It holds unit tests for how the hand-written LoadBalancerPoolHealthMonitor
// *AndPoll helpers interact with a caller-supplied response target, mirroring
// loadbalancerpoolmember_andpoll_custom_test.go.
//
// The helpers finish by fetching the pool's health monitor with Get. If the
// caller's WithResponseBodyInto were forwarded to that Get, the request layer
// would skip decoding, so the helper would hand back a nil monitor with a nil
// error. The helpers therefore fetch into their own value and write the same
// body to the caller's target afterwards.
//
// The tests are self-contained: each drives a local httptest.Server emulating the
// Cloud async task flow, so they run under a plain `go test` (or `scripts/test`)
// without needing the Prism/Steady mock server.

package cloud_test

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/G-Core/gcore-go"
	"github.com/G-Core/gcore-go/cloud"
	"github.com/G-Core/gcore-go/option"
	"github.com/G-Core/gcore-go/packages/param"
)

const (
	healthMonitorAndPollPoolID = "00000000-0000-4000-8000-0000000000p0"
	healthMonitorAndPollID     = "00000000-0000-4000-8000-0000000000h1"
)

// healthMonitorPayload is the monitor the fake server returns from GET.
func healthMonitorPayload() map[string]any {
	return map[string]any{
		"id":                  healthMonitorAndPollID,
		"type":                "HTTP",
		"delay":               10,
		"timeout":             5,
		"max_retries":         3,
		"max_retries_down":    3,
		"url_path":            "/",
		"expected_codes":      "200",
		"http_method":         "GET",
		"admin_state_up":      true,
		"operating_status":    "ONLINE",
		"provisioning_status": "ACTIVE",
	}
}

// newHealthMonitorFlowServer emulates the Cloud async flow for a pool health monitor:
//   - POST/PATCH .../healthmonitor returns a TaskIDList with actionTasks (pass an
//     empty slice to emulate a no-op PATCH, where the API creates no task)
//   - GET .../tasks/{id} returns a FINISHED task
//   - GET .../lbpools/{pool_id}/healthmonitor returns the monitor itself
func newHealthMonitorFlowServer(actionTasks []string) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/tasks/"):
			_ = json.NewEncoder(w).Encode(map[string]any{
				"id":                "50e2042d-761b-4f5a-b5bf-e11031c747b0",
				"state":             cloud.TaskStateFinished,
				"task_type":         "create_lbpool_health_monitor",
				"created_resources": map[string]any{"healthmonitors": []string{healthMonitorAndPollID}},
			})
		case r.Method == http.MethodGet:
			_ = json.NewEncoder(w).Encode(healthMonitorPayload())
		default: // the action: POST or PATCH .../healthmonitor
			_ = json.NewEncoder(w).Encode(map[string]any{"tasks": actionTasks})
		}
	}))
}

func newHealthMonitorFlowClient(server *httptest.Server) gcore.Client {
	return gcore.NewClient(
		option.WithBaseURL(server.URL),
		option.WithAPIKey("test"),
		option.WithCloudProjectID(1),
		option.WithCloudRegionID(1),
	)
}

// assertHealthMonitor checks the value the helper returned, which must be usable
// regardless of what response target the caller passed.
func assertHealthMonitor(t *testing.T, hm *cloud.HealthMonitor, err error) {
	t.Helper()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if hm == nil {
		t.Fatal("returned health monitor is nil: the caller's response target suppressed decoding")
	}
	if hm.ID != healthMonitorAndPollID {
		t.Errorf("hm.ID = %q, want %q", hm.ID, healthMonitorAndPollID)
	}
	if hm.Delay != 10 {
		t.Errorf("hm.Delay = %d, want 10", hm.Delay)
	}
}

// healthMonitorAndPollCall drives one helper against the fake server.
type healthMonitorAndPollCall struct {
	name   string
	invoke func(ctx context.Context, client gcore.Client, opts ...option.RequestOption) (*cloud.HealthMonitor, error)
	tasks  []string
}

func healthMonitorAndPollCalls() []healthMonitorAndPollCall {
	return []healthMonitorAndPollCall{
		{
			name:  "NewAndPoll",
			tasks: []string{"task-1"},
			invoke: func(ctx context.Context, client gcore.Client, opts ...option.RequestOption) (*cloud.HealthMonitor, error) {
				return client.Cloud.LoadBalancers.Pools.HealthMonitors.NewAndPoll(ctx, healthMonitorAndPollPoolID,
					cloud.LoadBalancerPoolHealthMonitorNewParams{Type: cloud.LbHealthMonitorTypeHTTP, Delay: 10, Timeout: 5, MaxRetries: 3}, opts...)
			},
		},
		{
			name:  "UpdateAndPoll",
			tasks: []string{"task-1"},
			invoke: func(ctx context.Context, client gcore.Client, opts ...option.RequestOption) (*cloud.HealthMonitor, error) {
				return client.Cloud.LoadBalancers.Pools.HealthMonitors.UpdateAndPoll(ctx, healthMonitorAndPollPoolID,
					cloud.LoadBalancerPoolHealthMonitorUpdateParams{Delay: param.NewOpt(int64(10))}, opts...)
			},
		},
		{
			// A PATCH that changes nothing creates no task; the helper skips polling
			// and goes straight to Get, and must still return the monitor.
			name:  "UpdateAndPoll/no-op",
			tasks: []string{},
			invoke: func(ctx context.Context, client gcore.Client, opts ...option.RequestOption) (*cloud.HealthMonitor, error) {
				return client.Cloud.LoadBalancers.Pools.HealthMonitors.UpdateAndPoll(ctx, healthMonitorAndPollPoolID,
					cloud.LoadBalancerPoolHealthMonitorUpdateParams{}, opts...)
			},
		},
	}
}

// Scenario 1 — no response target (plain SDK use): the helper returns the monitor.
func TestHealthMonitorAndPoll_NoResponseTarget(t *testing.T) {
	for _, call := range healthMonitorAndPollCalls() {
		t.Run(call.name, func(t *testing.T) {
			server := newHealthMonitorFlowServer(call.tasks)
			defer server.Close()

			hm, err := call.invoke(context.Background(), newHealthMonitorFlowClient(server))
			assertHealthMonitor(t, hm, err)
		})
	}
}

// Scenario 2 — **http.Response target (what the Terraform provider passes):
// the helper returns the monitor AND fills the caller's response with the
// monitor body, not the task list.
func TestHealthMonitorAndPoll_HTTPResponseTarget(t *testing.T) {
	for _, call := range healthMonitorAndPollCalls() {
		t.Run(call.name, func(t *testing.T) {
			server := newHealthMonitorFlowServer(call.tasks)
			defer server.Close()

			res := new(http.Response)
			hm, err := call.invoke(context.Background(), newHealthMonitorFlowClient(server),
				option.WithResponseBodyInto(&res))
			assertHealthMonitor(t, hm, err)

			if res == nil || res.Body == nil {
				t.Fatal("caller's *http.Response was not populated")
			}
			body, readErr := io.ReadAll(res.Body)
			if readErr != nil {
				t.Fatalf("reading caller's response body: %v", readErr)
			}
			var got cloud.HealthMonitor
			if err := json.Unmarshal(body, &got); err != nil {
				t.Fatalf("caller's response body is not a health monitor: %v (%s)", err, body)
			}
			if got.ID != healthMonitorAndPollID {
				t.Errorf("caller's response body has ID %q, want %q", got.ID, healthMonitorAndPollID)
			}
		})
	}
}

// Scenario 3 — *[]byte target (what the CLI passes): the helper returns the
// monitor AND fills the caller's byte slice.
func TestHealthMonitorAndPoll_ByteSliceTarget(t *testing.T) {
	for _, call := range healthMonitorAndPollCalls() {
		t.Run(call.name, func(t *testing.T) {
			server := newHealthMonitorFlowServer(call.tasks)
			defer server.Close()

			var raw []byte
			hm, err := call.invoke(context.Background(), newHealthMonitorFlowClient(server),
				option.WithResponseBodyInto(&raw))
			assertHealthMonitor(t, hm, err)

			if len(raw) == 0 {
				t.Fatal("caller's []byte target was not populated")
			}
			var got cloud.HealthMonitor
			if err := json.Unmarshal(raw, &got); err != nil {
				t.Fatalf("caller's bytes are not a health monitor: %v (%s)", err, raw)
			}
			if got.ID != healthMonitorAndPollID {
				t.Errorf("caller's bytes have ID %q, want %q", got.ID, healthMonitorAndPollID)
			}
		})
	}
}

// Scenario 4 — typed target: a caller that wants both the return value and its
// own decoded copy gets both.
func TestHealthMonitorAndPoll_TypedTarget(t *testing.T) {
	for _, call := range healthMonitorAndPollCalls() {
		t.Run(call.name, func(t *testing.T) {
			server := newHealthMonitorFlowServer(call.tasks)
			defer server.Close()

			var into cloud.HealthMonitor
			hm, err := call.invoke(context.Background(), newHealthMonitorFlowClient(server),
				option.WithResponseBodyInto(&into))
			assertHealthMonitor(t, hm, err)

			if into.ID != healthMonitorAndPollID {
				t.Errorf("caller's typed target has ID %q, want %q", into.ID, healthMonitorAndPollID)
			}
			if into.Delay != 10 {
				t.Errorf("caller's typed target has Delay %d, want 10", into.Delay)
			}
		})
	}
}

// A create must always produce exactly one task; an empty task list is an error,
// and so is a task that finishes in ERROR.
func TestHealthMonitorNewAndPoll_Failures(t *testing.T) {
	t.Run("no task created", func(t *testing.T) {
		server := newHealthMonitorFlowServer([]string{})
		defer server.Close()

		client := newHealthMonitorFlowClient(server)
		if _, err := client.Cloud.LoadBalancers.Pools.HealthMonitors.NewAndPoll(
			context.Background(), healthMonitorAndPollPoolID, cloud.LoadBalancerPoolHealthMonitorNewParams{},
		); err == nil {
			t.Fatal("NewAndPoll with no created task should return an error")
		}
	})

	t.Run("task failed", func(t *testing.T) {
		server := newTaskFlowServer(taskFlowConfig{taskState: cloud.TaskStateError, taskError: "boom"})
		defer server.Close()

		client := newTaskFlowClient(server)
		if _, err := client.Cloud.LoadBalancers.Pools.HealthMonitors.NewAndPoll(
			context.Background(), healthMonitorAndPollPoolID, cloud.LoadBalancerPoolHealthMonitorNewParams{},
		); err == nil {
			t.Fatal("NewAndPoll on a failed task should return an error")
		}
	})
}

// newHealthMonitorDeleteServer answers DELETE with deleteStatus, then serves each
// GET .../healthmonitor with the next status from getStatuses (the last one
// repeats). It counts the GETs it served.
func newHealthMonitorDeleteServer(deleteStatus int, getStatuses []int, gets *atomic.Int32) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == http.MethodDelete {
			w.WriteHeader(deleteStatus)
			return
		}
		n := int(gets.Add(1)) - 1
		status := getStatuses[min(n, len(getStatuses)-1)]
		w.WriteHeader(status)
		if status == http.StatusOK {
			_ = json.NewEncoder(w).Encode(healthMonitorPayload())
			return
		}
		_, _ = io.WriteString(w, `{"message":"status `+http.StatusText(status)+`"}`)
	}))
}

func healthMonitorDelete(server *httptest.Server, timeoutSeconds int64) error {
	client := newHealthMonitorFlowClient(server)
	return client.Cloud.LoadBalancers.Pools.HealthMonitors.DeleteAndPoll(
		context.Background(), healthMonitorAndPollPoolID, cloud.LoadBalancerPoolHealthMonitorDeleteParams{},
		option.WithMaxRetries(0),
		option.WithPollingIntervalSeconds(1),
		option.WithPollingTimeoutSeconds(timeoutSeconds),
	)
}

// The DELETE answers before the monitor is gone, so DeleteAndPoll waits for the
// GET to return 404, keeps polling through transient GET errors, and reports the
// last of them only when the polling timeout runs out.
func TestHealthMonitorDeleteAndPoll(t *testing.T) {
	t.Run("waits until the monitor is gone", func(t *testing.T) {
		var gets atomic.Int32
		server := newHealthMonitorDeleteServer(http.StatusNoContent, []int{http.StatusOK, http.StatusNotFound}, &gets)
		defer server.Close()

		if err := healthMonitorDelete(server, 30); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := gets.Load(); got != 2 {
			t.Errorf("served %d GETs, want 2", got)
		}
	})

	t.Run("keeps polling through a transient GET error", func(t *testing.T) {
		var gets atomic.Int32
		server := newHealthMonitorDeleteServer(http.StatusNoContent,
			[]int{http.StatusInternalServerError, http.StatusOK, http.StatusNotFound}, &gets)
		defer server.Close()

		if err := healthMonitorDelete(server, 30); err != nil {
			t.Fatalf("a transient GET error after a successful DELETE should not fail: %v", err)
		}
		if got := gets.Load(); got != 3 {
			t.Errorf("served %d GETs, want 3", got)
		}
	})

	t.Run("timeout reports the pool and the last error", func(t *testing.T) {
		var gets atomic.Int32
		server := newHealthMonitorDeleteServer(http.StatusNoContent, []int{http.StatusBadGateway}, &gets)
		defer server.Close()

		err := healthMonitorDelete(server, 2)
		if err == nil {
			t.Fatal("expected an error once the polling timeout runs out")
		}
		for _, want := range []string{healthMonitorAndPollPoolID, "still reported after delete", "502"} {
			if !strings.Contains(err.Error(), want) {
				t.Errorf("error %q does not mention %q", err, want)
			}
		}
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Errorf("error %q does not wrap context.DeadlineExceeded", err)
		}
	})

	t.Run("delete error is returned without polling", func(t *testing.T) {
		var gets atomic.Int32
		server := newHealthMonitorDeleteServer(http.StatusConflict, []int{http.StatusOK}, &gets)
		defer server.Close()

		if err := healthMonitorDelete(server, 30); err == nil {
			t.Fatal("expected the DELETE error")
		}
		if got := gets.Load(); got != 0 {
			t.Errorf("served %d GETs after a failed DELETE, want 0", got)
		}
	})
}
